import { useState } from 'react';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { ShopOrderByType } from '~/entities/shop/types';
import { useSelectBottomSheet } from '~/shared/ui/selects/use-select-bottom-sheet';

export const OrderByShopList = () => {
  const { closeBottomSheet } = useSelectBottomSheet();
  const close = () => {
    closeBottomSheet();
  };
  const { updateSearchParam, searchParam } = useShopSearch();
  const [sortType, setSortType] = useState(searchParam.listSearch.sortType || ShopOrderByType.가까운순);

  const handleSortType = () => {
    updateSearchParam({ sortType });
    close();
  };

  return (
    <div>
      <div className="btm-sheet-filter">
        <div className="filter-box">
          <h3>정렬 기준</h3>
          <div className="filter-item">
            <button
              type="button"
              className={`filter-rdo-btn ${sortType === ShopOrderByType.가까운순 ? 'on' : ''}`}
              onClick={() => {
                setSortType(ShopOrderByType.가까운순);
              }}
            >
              가까운 순
            </button>
            <button
              type="button"
              className={`filter-rdo-btn ${sortType === ShopOrderByType.가나다순 ? 'on' : ''}`}
              onClick={() => {
                setSortType(ShopOrderByType.가나다순);
              }}
            >
              가나다 순
            </button>
          </div>
        </div>
      </div>
      <div className="btm-btn-area confirm env-bottom">
        <button
          type="button"
          className="btm-btn env-bottom"
          onClick={() => {
            setSortType(ShopOrderByType.가까운순);
          }}
        >
          초기화
        </button>
        <button type="button" className="btm-btn app env-bottom" onClick={handleSortType}>
          사용처 보기
        </button>
      </div>
    </div>
  );
};
