import { useEffect, useState } from 'react';
import { NAVER_MAPS_READY_EVENT } from '~/entities/shop/lib/naver-map-sdk';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { useGeolocationQuery } from '~/entities/shop/model/geolocation-model';
import { getShopLocationSearchUpdate } from '~/entities/shop/model/shop-location-search';
import { ShopViewType } from '~/entities/shop/types';
import i18n from '~/shared/i18n/i18n';

type LocationAddress = {
  coordinateKey: string | null;
  text: string | null;
};

export const SearchInput = () => {
  const { updateSearchParam, searchParam } = useShopSearch();
  const { data: geolocation, refetch: refetchGeolocation } = useGeolocationQuery();
  const [searchText, setSearchText] = useState('');
  const [locationAddress, setLocationAddress] = useState<LocationAddress>({
    coordinateKey: null,
    text: i18n.t('common:checkingLocation'),
  });

  const position = geolocation?.position;
  const latitude = position?.latitude;
  const longitude = position?.longitude;
  const locationStatus = geolocation?.status;

  useEffect(() => {
    if (!geolocation) return;
    updateSearchParam(getShopLocationSearchUpdate(geolocation));
  }, [geolocation, updateSearchParam]);

  useEffect(() => {
    if (!geolocation) return;

    if (!position || latitude === undefined || longitude === undefined) {
      setLocationAddress({
        coordinateKey: null,
        text:
          geolocation.failureReason === 'permission-denied'
            ? i18n.t('common:notAllowedLocation')
            : i18n.t('common:notFoundLocation'),
      });
      return;
    }

    const coordinateKey = `${latitude}:${longitude}`;
    setLocationAddress((previousAddress) => {
      if (previousAddress.coordinateKey === coordinateKey) return previousAddress;
      return {
        coordinateKey,
        text: null,
      };
    });

    let active = true;
    const updateAddressFromNaver = () => {
      const maps = window.naver?.maps;
      if (!maps?.LatLng || !maps.Service?.reverseGeocode) return;

      maps.Service.reverseGeocode(
        {
          coords: new maps.LatLng(latitude, longitude),
        },
        (status, response) => {
          if (!active || status !== maps.Service.Status.OK) return;
          setLocationAddress({
            coordinateKey,
            text: response.v2.address.jibunAddress || null,
          });
        },
      );
    };

    updateAddressFromNaver();
    window.addEventListener(NAVER_MAPS_READY_EVENT, updateAddressFromNaver);

    return () => {
      active = false;
      window.removeEventListener(NAVER_MAPS_READY_EVENT, updateAddressFromNaver);
    };
  }, [geolocation, latitude, longitude, position]);

  const handleSearch = () => {
    updateSearchParam({ searchText });
  };

  const handleViewType = () => {
    updateSearchParam({
      viewType: searchParam.viewType === ShopViewType.SHOP_MAP ? ShopViewType.SHOP_LIST : ShopViewType.SHOP_MAP,
    });
  };

  const handleRefreshLocation = () => {
    void refetchGeolocation({ cancelRefetch: false });
  };

  const locationLabel = i18n.t('common:currentLocation');

  return (
    <div className="shop-search-area">
      <div className="shop-search-box">
        <div className="shop-search-ipt">
          <input
            type="text"
            className="search-ipt"
            placeholder={i18n.t('text:shopSearchPlaceholder')}
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
          />
          <button className="btn shop-search-btn" type="submit" onClick={handleSearch}>
            <span>{i18n.t('search')}</span>
          </button>
        </div>
        <button
          type="button"
          className={`btn shop-list-btn ${searchParam.viewType === ShopViewType.SHOP_MAP ? 'list' : ''}`}
          onClick={handleViewType}
        >
          <span>{i18n.t('common:showShopMap')}</span>
        </button>
      </div>
      <div className="user-location" data-location-status={locationStatus} onClick={handleRefreshLocation}>
        <span>{locationLabel}</span>
        <div className="location-description" role="status" aria-live="polite" aria-atomic="true">
          {locationAddress.text ? <p title={locationAddress.text}>{locationAddress.text}</p> : null}
        </div>
      </div>
    </div>
  );
};
