import { forwardRef } from 'react';
import { Place } from '~/entities/shop/dtos/types';
import { ShopItem } from '~/entities/shop/ui/shop-item';

type ShopListProps = {
  list: Place[];
};

export const ShopList = forwardRef<HTMLLIElement, ShopListProps>(function ShopList({ list }, ref) {
  return (
    <ul>
      {list.map((item, index) => {
        const isLastItem = list[list.length - 1].placeId === item.placeId;
        return (
          <ShopItem
            item={item}
            key={`${item.placeId}-${item.placeNm}-${item.placeCd}-${index}`}
            ref={isLastItem ? ref : undefined}
          />
        );
      })}
    </ul>
  );
});
