import { useSuspenseQuery } from '@tanstack/react-query';
import { ShopHistoryListRequestDTO, ShopListResponseDTO } from '~/entities/shop/dtos/shop-list';
import { DEFAULT_PLACE_READ_LIST_BY_RADIUS } from '~/entities/shop/model/constants';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import { shopApi } from './shop-api';

export const useShopListMapQuery = (
  param: ShopHistoryListRequestDTO = DEFAULT_PLACE_READ_LIST_BY_RADIUS,
  options?: QueryOptions<ShopListResponseDTO, CBDCAxiosError>,
) => {
  return useSuspenseQuery<ShopListResponseDTO, CBDCAxiosError>({
    queryKey: queries.voucher.placeReadListByRadiusMapList({ placeSearchParam: param }).queryKey,
    queryFn: () => shopApi.getPlaceReadListByRadius(param),
    select: (data) => {
      // data.result.newList = restructureList(data.result.list);
      return data;
    },
    gcTime: 5 * 60 * 1000, // 5분 동안 캐시 유지
    staleTime: 0,
    refetchOnMount: false, // 컴포넌트 마운트 시 자동 리페치 비활성화
    refetchOnWindowFocus: false, // 윈도우 포커스 시 자동 리페치 비활성화
    refetchOnReconnect: false, // 재연결 시 자동 리페치 비활성화
    ...options,
  });
};

export const resetShopListInMapListQuery = () => {
  const queryClient = getGlobalQueryClient();
  queryClient.invalidateQueries({
    queryKey: queries.voucher.placeReadListByRadiusMapList._def,
  });
};
