import { useMemo } from 'react';
import { useShopListInfiniteQuery } from '~/entities/shop/api/use-shop-infinite-list-query';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { ShopOrderByType } from '~/entities/shop/types';

export const useMergedShopInfiniteList = () => {
  const { searchParam } = useShopSearch();
  const { sortType, searchText, latitude, longitude, resYn } = searchParam.listSearch;
  const { data, hasNextPage, fetchNextPage, refetch, isLoading } = useShopListInfiniteQuery({
    sortType: sortType || ShopOrderByType.가까운순,
    searchText,
    latitude,
    longitude,
    page: 1,
    pageSize: 30,
    resYn,
  });

  const mergedList = useMemo(() => {
    if (!data?.pages) return [];
    return data.pages.map((page) => page.list).flat();
  }, [data]);

  return {
    mergedList,
    totalCount: data.pages[0]?.totalCount || 0,
    hasNextPage,
    fetchNextPage,
    refetch,
    isLoading,
    isEmpty: !data || mergedList?.length === 0,
    searchParam,
  };
};
