import { useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { ShopSearchParams, searchParamSchema } from '~/entities/shop/model/search-param';

type SearchParamUpdates = {
  mapSearch?: Partial<ShopSearchParams['mapSearch']>;
  listSearch?: Partial<ShopSearchParams['listSearch']>;
  viewType?: ShopSearchParams['viewType'];
};

export const useShopSearchParams = () => {
  const [searchParams, setSearchParams] = useSearchParams();

  const updateSearchParams = useCallback(
    (updates: SearchParamUpdates) => {
      // console.log('updateSearchParams', updates);
      requestAnimationFrame(() => {
        setSearchParams(
          (prev) => {
            const newParams = new URLSearchParams(prev);

            // mapSearch 업데이트
            if (updates.mapSearch) {
              Object.entries(updates.mapSearch).forEach(([key, value]) => {
                const paramKey = `mapSearch.${key}`;
                if (value === null || value === undefined) {
                  newParams.delete(paramKey);
                } else {
                  newParams.set(paramKey, value.toString());
                }
              });
            }

            // listSearch 업데이트
            if (updates.listSearch) {
              Object.entries(updates.listSearch).forEach(([key, value]) => {
                const paramKey = `listSearch.${key}`;
                if (value === null || value === undefined) {
                  newParams.delete(paramKey);
                } else {
                  newParams.set(paramKey, value.toString());
                }
              });
            }

            // viewType 업데이트
            if (updates.viewType !== undefined) {
              if (updates.viewType === null) {
                newParams.delete('viewType');
              } else {
                newParams.set('viewType', updates.viewType);
              }
            }

            return newParams;
          },
          { replace: true },
        );
      });
    },
    [setSearchParams],
  );

  const resetSearchParams = useCallback(() => {
    setSearchParams(new URLSearchParams(), { replace: true });
  }, [setSearchParams]);

  // URL 파라미터를 객체로 변환
  const params = Array.from(searchParams.entries()).reduce(
    (acc, [key, value]) => {
      const [prefix, field] = key.split('.');
      if (field) {
        // 중첩된 파라미터 처리 (mapSearch.xxx, listSearch.xxx)
        acc[prefix] = acc[prefix] || {};
        acc[prefix][field] = value;
      } else {
        // 최상위 파라미터 처리 (viewType)
        acc[key] = value;
      }
      return acc;
    },
    {} as Record<string, any>,
  );

  const parsedParams = searchParamSchema.parse(params);

  return {
    searchParams: parsedParams,
    updateSearchParams,
    resetSearchParams,
  };
};
