import { SwitchCase } from '@toss/react';
import { useSetHeaderTitle, useSetIsPullToRefreshEnabled } from '~/widgets/sub-layout/use-sub-layout';
import { useShopSearchParams } from '~/entities/shop/lib/use-shop-search-params';
import { ShopViewType } from '~/entities/shop/types';
import { MapContainer } from '~/entities/shop/ui/map-container';
import { OrderByShopContainer } from '~/entities/shop/ui/order-by-shop-container';
import { ShopListLayout } from '~/entities/shop/ui/shop-layout';
import { ShopListContainer } from '~/entities/shop/ui/shop-list-container';
import { NaverMapScript } from '~/entities/shop/ui/shop-naver-map-init';
import { useRefreshUserInfo } from '~/entities/user';
import i18n from '~/shared/i18n/i18n';

export const ShopListPage = () => {
  useSetHeaderTitle(i18n.t('usageLocation'));
  useSetIsPullToRefreshEnabled(true);
  useRefreshUserInfo();
  const { searchParams } = useShopSearchParams();
  const { viewType } = searchParams;

  return (
    <SwitchCase
      value={viewType as ShopViewType}
      caseBy={{
        [ShopViewType.SHOP_LIST]: (
          <ShopListLayout searchAreaContent={<OrderByShopContainer />} viewContent={<ShopListContainer />} />
        ),
        [ShopViewType.SHOP_MAP]: (
          <NaverMapScript>
            <ShopListLayout viewContent={<MapContainer />} />
          </NaverMapScript>
        ),
      }}
      defaultComponent={
        <ShopListLayout searchAreaContent={<OrderByShopContainer />} viewContent={<ShopListContainer />} />
      }
    />
  );
};
