import { forwardRef } from 'react';
import { Place } from '~/entities/shop/model/types';
import { ModalContainer } from '~/entities/shop/ui/modal-container';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type ShopItemProps = {
  item: Place;
};

export const ShopItem = forwardRef<HTMLLIElement, ShopItemProps>(function ShopItem({ item }, ref) {
  const showShopItemDetailModal = (clickedItem: Place) => () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog afterLeave={unmount} open={isOpen} onClose={close} buttonLabel={[]}>
          <ModalContainer item={clickedItem} />
        </Dialog>
      );
    });
  };

  return (
    <li key={item.placeId} ref={ref}>
      <button
        type="button"
        className={`shop-list-box ${item.isMyVoucher ? 'use' : ''}`}
        onClick={showShopItemDetailModal(item)}
      >
        {item.isMyVoucher && <p className="use">내 바우처 사용 가능</p>}
        <h3>{item.placeNm}</h3>
        <span className="shop-addr">
          <b>{item.DISTANCE_NM}</b> {item.adres}
        </span>
        <span className="shop-type">
          {item.indutyInfo && item.indutyInfo.length > 0 ? item.indutyInfo[0].indutyNm : ''}
        </span>
      </button>
    </li>
  );
});
